-- public.player_die(p_world uuid, p_uid uuid)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.player_die(p_world uuid, p_uid uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare w world; v_said text; v_grace double precision;
begin
  select * into w from world where id = p_world;
  -- What you were carrying goes into a grave where you fell, before the body
  -- is anywhere else: where it fell is where the grave goes.
  insert into private.fallen as f (world_id, uid, x, y, wx, wy, at)
  select p_world, p_uid, p.x, p.y, w.spawn_x, w.spawn_y, now()
    from player p where p.world_id = p_world and p.uid = p_uid
  on conflict (world_id, uid) do update set x = excluded.x, y = excluded.y, wx = excluded.wx, wy = excluded.wy, at = excluded.at;
  -- Inside the death grace (`death_grace_left`) nothing goes into a grave, and the line says the grace left.
  v_grace := death_grace_left(p_world, p_uid);
  v_said := case when v_grace is null then bury(p_world, p_uid)
                 else 'You have died. ' || death_grace_said(v_grace) || '; nothing lost.' end;
  perform kit_topup(p_world, p_uid);
  -- Whatever killed you stays with the body. The wounds that did it would
  -- open you again in a minute, and nothing you could do would be quick
  -- enough; waking up is waking up whole.
  update player set
      -- And inside the grace, stamina, food and water no lower than they were.
      stats = jsonb_build_object('health', 1,
                                 'stamina', greatest(0.5, case when v_grace is null then 0 else coalesce((stats->>'stamina')::double precision, 1) end),
                                 'hunger', greatest(0.6, case when v_grace is null then 0 else coalesce((stats->>'hunger')::double precision, 1) end),
                                 'thirst', greatest(0.6, case when v_grace is null then 0 else coalesce((stats->>'thirst')::double precision, 1) end),
                                 'hurtSettled', to_jsonb(now())),
      -- And where it fell, from the row as it was, for the body drawn lain there (`player.fell`).
      fell = jsonb_build_object('x', x, 'y', y, 'level', coalesce(level, 0), 'at', now()),
      wounds = '[]'::jsonb, x = w.spawn_x + 0.5, y = w.spawn_y + 0.5, level = 0,
      act = null, act_target = null, act_started = null, act_ends = null, act_left = null, act_goes = null,
      act_queue = '[]'::jsonb, moved_at = now(), aboard = null, seat = null
    where world_id = p_world and uid = p_uid;
  perform tell(p_world, p_uid, v_said, 'error');
end $function$
